{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.money import Money"
  ],
  "tests": [
    {
      "name": "test_allocate_rounding_leftover_distributed_to_earliest",
      "intent": "leftover cents are handed out one at a time to earliest parts with non-zero ratio",
      "code": "# intent: leftover cents are handed out one at a time to earliest parts with non-zero ratio\ndef test_allocate_rounding_leftover_distributed_to_earliest():\n    assert Money.of('100.00').allocate([1, 1, 1]) == [\n        Money.of('33.34'),\n        Money.of('33.33'),\n        Money.of('33.33'),\n    ]\n"
    },
    {
      "name": "test_allocate_parts_sum_to_total",
      "intent": "allocated parts always add up to the original amount",
      "code": "# intent: allocated parts always add up to the original amount\ndef test_allocate_parts_sum_to_total():\n    total = Money.of('100.00')\n    parts = total.allocate([1, 1, 1])\n    assert sum((p.amount for p in parts), Decimal('0.00')) == total.amount\n"
    },
    {
      "name": "test_allocate_with_zero_ratios_skips_them",
      "intent": "zero ratios receive no money and do not affect leftover distribution",
      "code": "# intent: zero ratios receive no money and do not affect leftover distribution\ndef test_allocate_with_zero_ratios_skips_them():\n    assert Money.of('1.00').allocate([0, 1, 0]) == [\n        Money.of('0.00'),\n        Money.of('1.00'),\n        Money.of('0.00'),\n    ]\n"
    },
    {
      "name": "test_allocate_single_ratio_gets_everything",
      "intent": "a single non-zero ratio receives the entire amount",
      "code": "# intent: a single non-zero ratio receives the entire amount\ndef test_allocate_single_ratio_gets_everything():\n    assert Money.of('5.00').allocate([1]) == [Money.of('5.00')]\n"
    },
    {
      "name": "test_allocate_negative_ratio_raises",
      "intent": "negative ratios are rejected with ValueError",
      "code": "# intent: negative ratios are rejected with ValueError\ndef test_allocate_negative_ratio_raises():\n    with pytest.raises(ValueError):\n        Money.of('1.00').allocate([1, -1])\n"
    },
    {
      "name": "test_allocate_all_zero_ratios_raises",
      "intent": "all zero ratios are rejected with ValueError",
      "code": "# intent: all zero ratios are rejected with ValueError\ndef test_allocate_all_zero_ratios_raises():\n    with pytest.raises(ValueError):\n        Money.of('1.00').allocate([0, 0])\n"
    }
  ]
}
